cat > /tmp/c.py <<'E'
import numpy as np,pandas as pd,glob
from scipy.optimize import curve_fit
fs=sorted(glob.glob('spectrum_*.csv'),reverse=True)
def L(x,a,c,w,b0,b1): return a*w**2/((x-c)**2+w**2)+b0+b1*(x-c)
wins={'A1p240':(240,225,256),'Ep289':(289,272,300),'283':(283,274,287),'305':(304.5,298,312),'320':(320.5,314,328),'Si520':(520,512,526),'531':(531,525,538),'457':(457,448,466),'432':(432,424,440),'481':(481,474,488),'582-586':(584,570,596),'600':(601,594,608)}
res={}
for f in fs:
    d=pd.read_csv(f);x,y=d.shift_cm1.values,d.intensity.values;e=float(f[9:15])
    row=[]
    for k,(c,lo,hi) in wins.items():
        m=(x>lo)&(x<hi)
        if m.sum()<8: row.append((k,None));continue
        try:
            p,cv=curve_fit(L,x[m],y[m],p0=[y[m].max()-np.median(y[m]),c,2,np.median(y[m]),0],maxfev=5000)
            s=np.sqrt(np.diag(cv)); row.append((k,round(p[0],2),round(p[1],1),round(abs(2*p[2]),1),round(s[0],2), round(np.pi*p[0]*abs(p[2]),2)))
        except Exception as ex: row.append((k,'fail'))
    print(e)
    for r in row: print('   ',r)
E
python -I /tmp/c.py

